{{ config(materialized='table') }}

with
quarantined as (
    select
        stage_entity_type,
        deal_external_identity,
        stage_type_code,
        stage_value_code,
        stage_effective_from,
        stage_record_source,
        stage_load_datetime,
        stage_recorded_at,
        stage_key,
        classification_value_name,
        classification_sort_order,
        violation_00,
        violation_01
    from {{ ref("reference__deal_stage_current__checked") }}
),
violations as (
    select
        'deal_external_identity_not_null' as rule_name,
        stage_entity_type,
        deal_external_identity,
        stage_type_code,
        stage_value_code,
        stage_effective_from,
        stage_record_source,
        stage_load_datetime,
        stage_recorded_at,
        stage_key,
        classification_value_name,
        classification_sort_order
    from quarantined
    where violation_00

    union all

    select
        'stage_effective_from_not_null' as rule_name,
        stage_entity_type,
        deal_external_identity,
        stage_type_code,
        stage_value_code,
        stage_effective_from,
        stage_record_source,
        stage_load_datetime,
        stage_recorded_at,
        stage_key,
        classification_value_name,
        classification_sort_order
    from quarantined
    where violation_01
)

select
    rule_name,
    stage_entity_type,
    deal_external_identity,
    stage_type_code,
    stage_value_code,
    stage_effective_from,
    stage_record_source,
    stage_load_datetime,
    stage_recorded_at,
    stage_key,
    classification_value_name,
    classification_sort_order
from violations
